            {"id": f"{fid}-q03", "text": f"Which matter, metric, value, unit, method, source, evidence, estimate, uncertainty, event time, knowledge time and successor lineage qualify {low}?", "kind": kinds[2], "answer_data": ["matter, impact, dependency, risk, opportunity, policy, action, target, metric, dimension, unit and value", "source system, dataset, method, factor, calculation, estimate, assumption, scenario, control and assurance reference", "reference, measurement, approval, assurance, publication, observation, ingestion and knowledge times, uncertainty, predecessor, successor and mapping loss"]},
